import { consultarPanaderiaService } from './service.mjs';

export async function handler(event) {
  const panaderiaId = Number(event.pathParameters.panaderiaId);
  const minimo = Number(event.queryStringParameters?.minimo ?? 0);
  const resultado = await consultarPanaderiaService(panaderiaId, minimo);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { buscarPanaderiaRepository, consultarPanaderiaRepository } from './repository.mjs';

export async function consultarPanaderiaService(panaderiaId, minimo) {
  const panaderia = await buscarPanaderiaRepository(panaderiaId);
  if (!panaderia) throw new Error('Panaderia no encontrado');
  const productos = await consultarPanaderiaRepository(panaderiaId, minimo);
  return { panaderia, productos };
}

import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_PRODUCTO, MODELO_PANADERIA } from '../../models/panaderia-producto.model.mjs';

export async function buscarPanaderiaRepository(panaderiaId) {
  const { Item } = await MODELO_PANADERIA.build(EntityRepository).get(
    { panaderiaId },
    { consistent: true }
  );
  return Item ?? null;
}

export async function consultarPanaderiaRepository(panaderiaId, minimo) {
  const { Items = [] } = await MODELO_PRODUCTO.build(EntityRepository).query(
    { index: 'PorPanaderia', partition: panaderiaId },
    { filters: { Producto: { attr: 'precioCentimos', gte: minimo } } }
  );
  return Items;
}
